macro.command:
if(args[0] === "on") {
    let effectData = token.actor.appliedEffects.find(e => DAE.effectMatchesSource(e, item.uuid) && e.name === item.name);
    if(!effectData) return;
    const originTokenUuid = effectData.getFlag("gambits-premades", "festeringFeverTokenUuid") ?? args[3];
    let effectOriginToken = await fromUuid(originTokenUuid);
    if(!effectOriginToken) return;
    let castTotal = effectData.getFlag("gambits-premades", "festeringFeverCastTotal") ?? Number(args[1]);
    if(!castTotal) return;
    let spellDC = effectData.getFlag("gambits-premades", "festeringFeverSpellDC") ?? Number(args[2]);
    await effectData.update({
        "flags.gambits-premades.festeringFeverCastTotal": castTotal,
        "flags.gambits-premades.festeringFeverSpellDC": spellDC,
        "flags.gambits-premades.festeringFeverTokenUuid": originTokenUuid
    });
    const chainId = effectData.getFlag("gambits-premades", "feverChain") ?? effectData.id;
    await effectData.setFlag("gambits-premades", "feverChain", chainId);
    await actor.setFlag("gambits-premades", `feverChains.${chainId}`, true);

    const itemData = game.gps.disableBlfxAutoRecognition({
        name: item.name,
        img: item.img,
        type: "feat",
        effects: [],
        flags: {
            "midi-qol": {
                noProvokeReaction: true,
                onUseMacroName: null,
                forceCEOff: true
            },
            "autoanimations": {
                version: 5,
                isEnabled: false,
                killAnim: true
            }
        },
        system: {
            activities: {
                gpsSynthetic0001: {
                    type: "save",
                    midiProperties: { magicEffect: true, magicDamage: true },
                    activation: { type: "special" },
                    consumption: { spellSlot: false, targets: [] },
                    target: { affects: { type: "creature", count: "1" } },
                    save: { ability: ["con"], dc: { calculation: "", formula: String(spellDC) } },
                    damage: { onSave: "half", parts: [{ custom: { enabled: true, formula: `${castTotal}d8` }, types: ["necrotic"] }] }
                }
            }
        }
    });

    const itemUpdate = new CONFIG.Item.documentClass(itemData, { parent: effectOriginToken.actor });
    const options = { showFullCard: false, createWorkflow: true, versatile: false, configureDialog: false, targetUuids: [token.document.uuid], workflowOptions: {autoRollDamage: 'always', autoFastDamage: true} };
    const saveResult = await MidiQOL.completeItemUse(itemUpdate, { midiOptions: options }, { configure: false }, {});

    if (!saveResult || saveResult.aborted) return;

    let content;

    if (saveResult.failedSaves.size === 0 || castTotal === 1) {
        if(saveResult.failedSaves.size === 0) {
            content = `<span style='text-wrap: wrap;'>The target saves for half damage and the fever subsides.<br><img src="${token.actor.img}" width="30" height="30" style="border:0px"></span>`;
        }
        else if(castTotal === 1) {
            content = `<span style='text-wrap: wrap;'>The target does not save but the fever subsides as its energy runs out.<br><img src="${token.actor.img}" width="30" height="30" style="border:0px"></span>`;
        }
        await MidiQOL.socket().executeAsGM("removeEffects", { actorUuid: token.actor.uuid, effects: [effectData.id] });

        let targets = canvas.tokens.placeables.filter(t => {
            if (t.document.disposition !== token.document.disposition) return;
            if (!t.actor.getFlag("gambits-premades", `feverChains.${chainId}`)) return;
            return t;
        });

        if (targets.length === 0) return;

        for(let target of targets) {
            await target.actor.unsetFlag("gambits-premades", `feverChains.${chainId}`);
        }
    }
    else {
        content = `<span style='text-wrap: wrap;'>The target does not save and the fever continues to fester.<br><img src="${token.actor.img}" width="30" height="30" style="border:0px"></span>`;
    }

    if(game.gps.getCprConfig({itemUuid: item.uuid}).animEnabled) {
        new Sequence()

        .effect()
        .file("jb2a.magic_signs.rune.necromancy.complete.green")
        .attachTo(token)
        .scaleToObject(2.5)
        .opacity(1)
        .zIndex(1)
        .belowTokens(false)
        .fadeIn(1500)
        .fadeOut(1500)
        .filter("ColorMatrix", { hue: 140, brightness: 0.8, contrast: 1, saturate: 1 })

        .play()
    }

    let actorPlayer = MidiQOL.playerForActor(effectOriginToken.actor);

    let chatData = {
        user: actorPlayer.id,
        speaker: ChatMessage.getSpeaker({ token: effectOriginToken }),
        content: game.i18n.localize(content)
    };
    ChatMessage.create(chatData);
}

else if(args[0] === "each") {
    let effectData = token.actor.appliedEffects.find(e => DAE.effectMatchesSource(e, item.uuid) && e.name === item.name);
    if(!effectData) return;
    let effectOriginToken = await fromUuid(effectData.getFlag("gambits-premades", "festeringFeverTokenUuid"));
    if(!effectOriginToken) return;
    let castTotal = await effectData.getFlag("gambits-premades", "festeringFeverCastTotal");
    if(!castTotal) return;

    const chainId = effectData.getFlag("gambits-premades", "feverChain") ?? effectData.id;
    castTotal = castTotal - 1;
    await effectData.setFlag("gambits-premades", "festeringFeverCastTotal", castTotal);

    const rangeCheck = MidiQOL.findNearby(null, token, 10, { includeToken: false });
    const withinRange = rangeCheck.filter(t => (!t.actor.getFlag("gambits-premades", `feverChains.${chainId}`)) && t.document.disposition === token.document.disposition);

    if (withinRange.length > 0) {
        const randomToken = withinRange[Math.floor(Math.random() * withinRange.length)];
        await MidiQOL.socket().executeAsGM("createEffects", { actorUuid: randomToken.actor.uuid, effects: [{...effectData.toObject(), _id: foundry.utils.randomID()}] });
    }
    else {
        let targets = canvas.tokens.placeables.filter(t => {
            if (t.document.disposition !== token.document.disposition) return;
            if (!t.actor.getFlag("gambits-premades", `feverChains.${chainId}`)) return;
            return t;
        });

        for(let target of targets) {
            await target.actor.unsetFlag("gambits-premades", `feverChains.${chainId}`);
        }

        let content = `<span style='text-wrap: wrap;'>The fever subsides on the target and there are no additional targets within 10 feet.<br><img src="${token.actor.img}" width="30" height="30" style="border:0px"></span>`;

        let actorPlayer = MidiQOL.playerForActor(effectOriginToken.actor);

        let chatData = {
            user: actorPlayer.id,
            speaker: ChatMessage.getSpeaker({ token: effectOriginToken }),
            content: game.i18n.localize(content)
        };
        ChatMessage.create(chatData);
    }

    await MidiQOL.socket().executeAsGM("removeEffects", { actorUuid: actor.uuid, effects: [effectData.id] });
}
